const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function policyLinks(){return Object.entries(policies).map(([id,p])=>`<a href="#/${id}" data-close-policy class="policy-link">${({terms:'Terms',privacy:'Privacy',safety:'Child safety & AI',storage:'Cookies & storage'})[id]}</a>`).join('')}
export function policyPage(id){if(!Object.hasOwn(policies,id))return '';const p=policies[id];return `<section class="policy-page"><a class="back" href="#/discover">Back to Discover</a><div class="page-intro"><div><span class="eyebrow">ZUNO KIDS · POLICIES</span><h1>${p.title}</h1><p>${p.intro}</p></div></div><nav class="policy-nav" aria-label="Policy pages">${policyLinks()}</nav><p class="policy-updated">Current preview · Updated ${policyUpdated}</p><details class="policy-toc"><summary>On this page · ${p.sections.length} sections</summary>${p.sections.map(([title],i)=>`<button data-policy-jump="policy-${id}-${i}">${i+1}. ${esc(title)}</button>`).join('')}</details><article class="policy-reader">${p.sections.map(([title,...paras],i)=>`<section id="policy-${id}-${i}"><h2>${i+1}. ${esc(title)}</h2>${paras.map(t=>`<p>${esc(t)}</p>`).join('')}</section>`).join('')}<section><h2>Official information and contact</h2><div class="policy-nav"><a href="https://clerkops.co.ke/contact" target="_blank" rel="noopener noreferrer" data-external="true">ClerkOps contact ↗</a><a href="https://www.odpc.go.ke/data-protection-laws-kenya/" target="_blank" rel="noopener noreferrer" data-external="true">Kenya data-protection laws ↗</a><a href="https://www.odpc.go.ke/rights-of-a-data-subject/" target="_blank" rel="noopener noreferrer" data-external="true">ODPC rights information ↗</a><a href="/third-party.html">Open-source acknowledgements</a></div><p>These notices describe the current preview and do not certify legal compliance. The operator’s actual practices and legal identity require confirmation before a child-account launch.</p></section></article></section>`}
